// Some portions generated by Codex
package org.eclipse.rdf4j.benchmark.common;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.rio.helpers.AbstractRDFHandler;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;

class VirtualThemeCatalogProfileTest {

	private static final String BASE = "http://example.com/theme/";
	private static final IRI UNTYPED = SimpleValueFactory.getInstance().createIRI("urn:store-profile:untyped-resource");

	@Test
	void allVirtualCatalogCountsMatchIndependentPhysicalDataProfile() {
		Profile profile = new Profile();
		for (Theme theme : Theme.values()) {
			if (theme != Theme.ANALYTICS && theme != Theme.EXPLORATION) {
				profile.add(theme);
			}
		}
		profile.finishIncoming();

		assertFalse(profile.graphs.isEmpty(), "Virtual queries require a populated combined dataset");
		long predicates = profile.predicates.size();
		long classes = profile.classes.size();
		long[] analytics = { 1, 1, predicates, classes, predicates, profile.datatypes.size(),
				profile.outgoingDegrees.size(), profile.classProperties.size(), profile.classLinks.size(),
				profile.highIncomingObjects, 1, predicates, profile.namespaces.size() };
		long[] exploration = { 1, profile.graphs.size(), predicates, profile.graphPredicates.size(), classes,
				profile.literalProfiles.size(), profile.classProperties.size(), profile.objectClasses.size(),
				2 * predicates, profile.predicatePairs.size(), Math.min(200, profile.signatures.size()),
				profile.classPairs.size(), profile.outgoingDegrees.size() + profile.incomingDegrees.size() };

		List<Executable> checks = new ArrayList<>();
		addChecks(checks, Theme.ANALYTICS, analytics);
		addChecks(checks, Theme.EXPLORATION, exploration);
		checks.add(() -> assertEquals(classes,
				ThemeQueryCatalog.expectedCountBindingValueFor(Theme.ANALYTICS, 0).orElseThrow(),
				"Analytics distinct class count binding"));
		checks.add(() -> assertEquals(predicates,
				ThemeQueryCatalog.expectedCountBindingValueFor(Theme.ANALYTICS, 1).orElseThrow(),
				"Analytics distinct predicate count binding"));
		checks.add(() -> assertEquals(profile.subjectsAlsoObjects,
				ThemeQueryCatalog.expectedCountBindingValueFor(Theme.ANALYTICS, 10).orElseThrow(),
				"Analytics subjects also occurring as objects count binding"));
		assertAll("Every virtual query over all default physical themes", checks);
	}

	private static void addChecks(List<Executable> checks, Theme theme, long[] actual) {
		assertEquals(ThemeQueryCatalog.QUERY_COUNT, actual.length);
		for (int index = 0; index < actual.length; index++) {
			int selected = index;
			checks.add(() -> assertEquals(actual[selected], ThemeQueryCatalog.expectedCountFor(theme, selected),
					theme + " query " + selected + ": "
							+ ThemeQueryCatalog.benchmarkQueryFor(theme, selected).getName()));
		}
	}

	/**
	 * The physical generators own disjoint entity namespaces. Check that premise against every emitted statement so
	 * per-theme maps can be released after projection; shared external resource objects are aggregated separately.
	 * These are fixture checks, not a restriction on query-engine RDF inputs.
	 */
	private static String entityPrefix(Theme theme) {
		return BASE + switch (theme) {
		case MEDICAL_RECORDS -> "medical/";
		case SOCIAL_MEDIA -> "social/";
		case LIBRARY -> "library/";
		case ENGINEERING -> "engineering/";
		case HIGHLY_CONNECTED -> "connected/";
		case TRAIN -> "train/";
		case ELECTRICAL_GRID -> "grid/";
		case PHARMA -> "pharma/";
		case SPARSE -> "sparse/";
		case ADAPTIVE_FILTER_PLACEMENT -> "adaptive-filter/";
		case REAL_ESTATE -> "realestate/";
		case DATA_TRANSFORMATION -> "data-transformation/";
		case ANALYTICS, EXPLORATION -> throw new IllegalArgumentException("Not a physical theme: " + theme);
		};
	}

	private static final class Profile {
		private final Set<IRI> graphs = new HashSet<>();
		private final Set<IRI> predicates = new HashSet<>();
		private final Set<IRI> classes = new HashSet<>();
		private final Set<IRI> datatypes = new HashSet<>();
		private final Set<String> namespaces = new HashSet<>();
		private final Set<PredicatePair> graphPredicates = new HashSet<>();
		private final Set<LiteralProfile> literalProfiles = new HashSet<>();
		private final Set<PredicatePair> classProperties = new HashSet<>();
		private final Set<PredicatePair> classLinks = new HashSet<>();
		private final Set<PredicatePair> objectClasses = new HashSet<>();
		private final Set<PredicatePair> predicatePairs = new HashSet<>();
		private final Set<PredicatePair> classPairs = new HashSet<>();
		private final Set<Long> outgoingDegrees = new HashSet<>();
		private final Set<Long> incomingDegrees = new HashSet<>();
		private final Set<String> signatures = new HashSet<>();
		private final Map<IRI, Long> externalIncoming = new HashMap<>();
		private long highIncomingObjects;
		private long subjectsAlsoObjects;

		void add(Theme theme) {
			String prefix = entityPrefix(theme);
			List<String> foreignPrefixes = Arrays.stream(Theme.values())
					.filter(other -> other != theme && other != Theme.ANALYTICS && other != Theme.EXPLORATION)
					.map(VirtualThemeCatalogProfileTest::entityPrefix)
					.toList();
			Map<Resource, Set<PredicateValue>> outgoing = new HashMap<>();
			Map<IRI, Set<SubjectPredicate>> incoming = new HashMap<>();
			ThemeDataSetGenerator.generate(theme, new AbstractRDFHandler() {
				@Override
				public void handleStatement(Statement statement) {
					IRI subject = assertInstanceOf(IRI.class, statement.getSubject(), "Physical subject fixture");
					assertTrue(subject.stringValue().startsWith(prefix), "Physical theme owns its subject namespace");
					IRI graph = assertInstanceOf(IRI.class, statement.getContext(), "Physical named graph");
					graphs.add(graph);
					if (predicates.add(statement.getPredicate())) {
						namespaces.add(statement.getPredicate().stringValue().replaceAll("[^/#]+$", ""));
					}
					graphPredicates.add(new PredicatePair(graph, statement.getPredicate()));
					outgoing.computeIfAbsent(subject, ignored -> new HashSet<>())
							.add(new PredicateValue(statement.getPredicate(), statement.getObject()));
					if (statement.getObject() instanceof IRI iri) {
						for (String foreignPrefix : foreignPrefixes) {
							assertFalse(iri.stringValue().startsWith(foreignPrefix),
									"Fixture cross-theme resource edge requires a global data profile");
						}
						incoming.computeIfAbsent(iri, ignored -> new HashSet<>())
								.add(new SubjectPredicate(subject, statement.getPredicate()));
					} else {
						Literal literal = assertInstanceOf(Literal.class, statement.getObject(),
								"Physical object fixture");
						datatypes.add(literal.getDatatype());
						literalProfiles.add(new LiteralProfile(statement.getPredicate(), literal.getDatatype(),
								literal.getLanguage().orElse("").toLowerCase(Locale.ROOT)));
					}
				}
			});
			assertFalse(outgoing.isEmpty(), "Every physical theme contributes statements");
			for (Map.Entry<IRI, Set<SubjectPredicate>> entry : incoming.entrySet()) {
				long degree = entry.getValue().size();
				if (entry.getKey().stringValue().startsWith(prefix)) {
					recordIncoming(degree);
				} else {
					externalIncoming.merge(entry.getKey(), degree, Math::addExact);
				}
			}
			for (Map.Entry<Resource, Set<PredicateValue>> entry : outgoing.entrySet()) {
				Resource subject = entry.getKey();
				Set<PredicateValue> values = entry.getValue();
				outgoingDegrees.add((long) values.size());
				if (incoming.containsKey(subject)) {
					subjectsAlsoObjects++;
				}
				Set<IRI> subjectClasses = types(values);
				classes.addAll(subjectClasses);
				addPairs(classPairs, subjectClasses);
				Set<IRI> subjectPredicates = new HashSet<>();
				Map<FeatureKind, Long> features = new HashMap<>();
				for (PredicateValue value : values) {
					subjectPredicates.add(value.predicate());
					String kind = value.value() instanceof IRI ? "IRI" : "LITERAL";
					features.merge(new FeatureKind(value.predicate(), kind), 1L, Math::addExact);
					if (!value.predicate().equals(RDF.TYPE)) {
						for (IRI type : subjectClasses) {
							classProperties.add(new PredicatePair(type, value.predicate()));
						}
					}
					if (value.value() instanceof IRI iri) {
						Set<IRI> objectTypes = types(outgoing.getOrDefault(iri, Set.of()));
						for (IRI objectType : objectTypes.isEmpty() ? Set.of(UNTYPED) : objectTypes) {
							objectClasses.add(new PredicatePair(value.predicate(), objectType));
						}
						if (!value.predicate().equals(RDF.TYPE)) {
							for (IRI sourceType : subjectClasses) {
								for (IRI targetType : objectTypes) {
									classLinks.add(new PredicatePair(sourceType, targetType));
								}
							}
						}
					}
				}
				addPairs(predicatePairs, subjectPredicates);
				List<String> orderedFeatures = features.entrySet()
						.stream()
						.map(feature -> feature.getKey().predicate().stringValue() + " [" + feature.getKey().kind()
								+ "] x" + feature.getValue())
						.sorted()
						.toList();
				signatures.add(String.join(" | ", orderedFeatures));
			}
		}

		void finishIncoming() {
			externalIncoming.values().forEach(this::recordIncoming);
		}

		private void recordIncoming(long degree) {
			incomingDegrees.add(degree);
			if (degree >= 1000) {
				highIncomingObjects++;
			}
		}

		private static Set<IRI> types(Set<PredicateValue> values) {
			Set<IRI> result = new HashSet<>();
			for (PredicateValue value : values) {
				if (value.predicate().equals(RDF.TYPE)) {
					result.add(assertInstanceOf(IRI.class, value.value(), "Physical class fixture"));
				}
			}
			return result;
		}

		private static void addPairs(Set<PredicatePair> pairs, Set<IRI> values) {
			List<IRI> sorted = values.stream()
					.sorted((left, right) -> left.stringValue().compareTo(right.stringValue()))
					.toList();
			for (int first = 0; first < sorted.size(); first++) {
				for (int second = first + 1; second < sorted.size(); second++) {
					pairs.add(new PredicatePair(sorted.get(first), sorted.get(second)));
				}
			}
		}
	}

	private record PredicateValue(IRI predicate, Value value) {
	}

	private record SubjectPredicate(Resource subject, IRI predicate) {
	}

	private record PredicatePair(IRI first, IRI second) {
	}

	private record LiteralProfile(IRI predicate, IRI datatype, String language) {
	}

	private record FeatureKind(IRI predicate, String kind) {
	}
}
